import{_ as o,o as a,c as t,ae as d}from"./chunks/framework.B3uLoxsb.js";const u=JSON.parse('{"title":"Por que usar cw no GPT Codex + VS Code","description":"","frontmatter":{},"headers":[],"relativePath":"pt/strategy/why-cw.md","filePath":"pt/strategy/why-cw.md","lastUpdated":1771052491000}'),r={name:"pt/strategy/why-cw.md"};function i(c,e,s,l,n,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="por-que-usar-cw-no-gpt-codex-vs-code" tabindex="-1">Por que usar <code>cw</code> no GPT Codex + VS Code <a class="header-anchor" href="#por-que-usar-cw-no-gpt-codex-vs-code" aria-label="Permalink to &quot;Por que usar `cw` no GPT Codex + VS Code&quot;">​</a></h1><p>O <code>cw</code> padroniza como você planeja, executa e valida tarefas com o Codex no VS Code.</p><p>Sem esse padrão, equipes tendem a ter prompts inconsistentes, validação fraca e releases manuais mais suscetíveis a erro.</p><p>Com <code>cw</code>, você ganha workflows explícitos, gates de qualidade, automação de release e onboarding mais rápido.</p><h2 id="problema-que-o-cw-resolve" tabindex="-1">Problema que o <code>cw</code> resolve <a class="header-anchor" href="#problema-que-o-cw-resolve" aria-label="Permalink to &quot;Problema que o `cw` resolve&quot;">​</a></h2><p>Sem um modelo operacional, o uso do Codex em projetos maiores tende a apresentar:</p><ul><li>prompts inconsistentes entre colaboradores;</li><li>transição fraca entre planejamento, implementação e validação;</li><li>etapas de release e governança puladas sob pressão;</li><li>retrabalho de setup em repositórios diferentes.</li></ul><h2 id="o-que-o-cw-adiciona" tabindex="-1">O que o <code>cw</code> adiciona <a class="header-anchor" href="#o-que-o-cw-adiciona" aria-label="Permalink to &quot;O que o `cw` adiciona&quot;">​</a></h2><p>O <code>cw</code> adiciona um modelo repetível de execução sobre o Codex:</p><ul><li>ativação explícita de workflow (<code>cw /orchestrate</code>, <code>cw /debug</code>, etc.);</li><li>contratos codex-native para o comportamento dos fluxos;</li><li>packs de validação por domínio e stack (Node, Python e Rust);</li><li>automação de CI e release alinhada com a operação real;</li><li>documentação multilíngue e playbooks operacionais.</li></ul><h2 id="comparativo-com-e-sem-cw" tabindex="-1">Comparativo: com e sem <code>cw</code> <a class="header-anchor" href="#comparativo-com-e-sem-cw" aria-label="Permalink to &quot;Comparativo: com e sem `cw`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimensão</th><th>Sem <code>cw</code></th><th>Com <code>cw</code></th></tr></thead><tbody><tr><td>Início de tarefa</td><td>Estilo de prompt varia por pessoa</td><td>Trigger explícito de workflow e objetivo</td></tr><tr><td>Trabalho multidomínio</td><td>Coordenação ad hoc</td><td><code>/orchestrate</code> com fases estruturadas</td></tr><tr><td>Disciplina de validação</td><td>Fácil pular checks</td><td>Rotinas de validação e gates de CI</td></tr><tr><td>Higiene de release</td><td>Manual e sujeito a erro</td><td>Fluxo automatizado de tag/changelog/release</td></tr><tr><td>Onboarding</td><td>Conhecimento disperso no chat</td><td>Docs, exemplos e comandos centralizados</td></tr><tr><td>Repetibilidade</td><td>Depende da memória individual</td><td>Convenções e checks de repositório</td></tr></tbody></table><h2 id="quando-o-cw-nao-e-necessario" tabindex="-1">Quando o <code>cw</code> não é necessário <a class="header-anchor" href="#quando-o-cw-nao-e-necessario" aria-label="Permalink to &quot;Quando o `cw` não é necessário&quot;">​</a></h2><p>Para tarefas muito pequenas e pontuais, prompts diretos no Codex podem bastar.</p><p>O <code>cw</code> passa a valer mais quando você precisa de:</p><ul><li>consistência entre colaboradores;</li><li>gates de qualidade auditáveis;</li><li>operação e release em escala.</li></ul><h2 id="recomendacao-pratica" tabindex="-1">Recomendação prática <a class="header-anchor" href="#recomendacao-pratica" aria-label="Permalink to &quot;Recomendação prática&quot;">​</a></h2><p>Use um modelo misto:</p><ol><li>Tarefa simples: prompt direto.</li><li>Trabalho de produto: workflows <code>cw</code> + validações.</li><li>Ciclo de release: automação de checks e pipeline.</li></ol>',19)])])}const h=o(r,[["render",i]]);export{u as __pageData,h as default};
